  function calculateRemainingTimeToDeadline(
    userId: string,
    reportDate: Date,
    currentTime?: Date
  ): { remainingMinutes: number; deadline: Date; isOverdue: boolean; displayText: string } {
    const now = currentTime || new Date();
    
    const deadlineInfo = getReportSubmissionDeadline(
      userId,
      reportDate,
      userId
    );
    
    const deadline = deadlineInfo.deadlineDateTime;
    const diffMs = deadline.getTime() - now.getTime();
    const remainingMinutes = Math.floor(diffMs / (1000 * 60));
    const isOverdue = remainingMinutes < 0;
    
    let displayText: string;
    if (isOverdue) {
      displayText = '期限超過';
    } else if (remainingMinutes === 0) {
      displayText = 'あと0分';
    } else {
      displayText = `あと${remainingMinutes}分`;
    }
    
    return {
      remainingMinutes,
      deadline,
      isOverdue,
      displayText
    };
  }
  return { calculateRemainingTimeToDeadline };
